import{_ as r,a0 as a,w as p,s,ao as u,I as i,x as e,a1 as l,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"Linux能夠提供消費者想要的東西嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux能夠提供消費者想要的東西嗎？ | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux能夠提供消費者想要的東西嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux能夠提供消費者想要的東西嗎？ | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20140818 Will Linux ever be able to give consumers what they want","title":"Linux能夠提供消費者想要的東西嗎？","tag":"201412","desc":""},"relativePath":"201412/20140818 Will Linux ever be able to give consumers what they want.md","filePath":"[post].md"}'),x={name:"201412/20140818 Will Linux ever be able to give consumers what they want.md"};function b(L,t,m,d,w,f){const o=a("Link");return p(),s("div",null,[t[18]||(t[18]=u('<h1 id="linux能夠提供消費者想要的東西嗎" tabindex="-1">Linux能夠提供消費者想要的東西嗎？ <a class="header-anchor" href="#linux能夠提供消費者想要的東西嗎" aria-label="Permalink to “Linux能夠提供消費者想要的東西嗎？”">​</a></h1><blockquote><p>由Jack Wallen提出的新觀點，提供消費者想要的東西也許是收穫無限成就的關鍵。</p></blockquote><p><img src="http://tr2.cbsistatic.com/hub/i/r/2014/08/14/ce90a81e-d17b-4b8f-bd5b-053120e305e6/resize/620x485/f5f9e0798798172d4e41edbedeb6b7e5/whattheyneedhero.png" alt=""></p><p>在消費電子的世界裏，如果你不能提供購買者想要的東西，那他們就會跑去別家。我們最近在Firefox瀏覽器上就看過類似的事情。消費者想要的是一個快速而不那麼臃腫的軟件，而開發者們卻走到了另外的方向上。最後，用户都轉移到Chrome或Chromium上去了。</p><p>Linux需要深深凝視自己的水晶球，仔細體會那場瀏覽器大戰留下的塵埃，然後留意一下這點建議：</p><blockquote><p>如果你不能提供他們想要的，他們就會離開。</p></blockquote><p>而這種事與願違的另一個例子是Windows 8。消費者不喜歡那套界面。而微軟卻堅持使用，因為這是把所有東西搬到Surface平板上所必須的。相同的情況也可能發生在Canonical和Ubuntu Unity身上 -- 儘管它們的目標並不是單一獨特地針對平板電腦來設計（所以，整套界面在桌面系統上仍然很實用而且直觀）。</p><p>一直以來，Linux開發者和設計者們看上去都按照他們自己的想法來做事情。他們過分在意“吃你自家的狗糧”這句話了。以至於他們忘記了一件非常重要的事情：</p><blockquote><p>沒有新用户，他們的“根基”也僅僅只屬於他們自己。</p></blockquote><p>換句話説，唱詩班不僅僅是被傳道，他們也同時在宣傳。讓我給你看三個案例來完全掌握這一點。</p>',10)),i("ul",null,[t[3]||(t[3]=i("li",null,"多年以來，一直有在Linux系統中替代活動目錄（Active Directory）的需求。我很想把這個名稱換成LDAP，但是你真的用過LDAP嗎？那就是個噩夢。開發者們也努力了想讓LDAP能易用一點，但是沒一個做到了。而讓我很震驚的是這樣一個從多用户環境下發展起來的平台居然沒有一個能和AD正面較量的功能。這需要一組開發人員，從頭開始建立一個AD的開源替代。這對那些尋求從微軟產品遷移的中型企業來説是非常大的福利。但是在這個產品做好之前，他們還不能開始遷移。",-1)),t[4]||(t[4]=i("li",null,"另一個從微軟激發的需求是Exchange/Outlook。是，我也知道許多人都開始用雲。但是，事實上中等和大型規模生意仍然依賴於Exchange/Outlook組合，直到能有更好的產品出現。而這將非常有希望發生在開源社區。整個拼圖的一小塊已經擺好了（雖然還需要一些工作）- 羣件客户端，Evolution。如果有人能夠從Zimbra拉出一個分支，然後重新設計成可以配合Evolution（甚至Thunderbird）來提供服務實現Exchange的簡單替代，那這個遊戲就不是這麼玩了，而消費者獲得的利益將是巨大的。",-1)),i("li",null,[t[1]||(t[1]=e("便宜，便宜，還是便宜。這是大多數人都得嚥下去的苦藥片 - 但是消費者（和生意）就是希望便宜。看看去年一年Chromebook的銷量吧。現在，搜索一下Linux筆記本看能不能找到700美元以下的。而只用三分之一的價格，就可以買到一個讓你夠用的Chromebook（一個使用了Linux內核的平台）。但是因為Linux仍然是一個細分市場，很難降低成本。像紅帽那種公司也許可以改變現狀。他們也已經推出了服務器硬件。為什麼不推出一些和Chromebook有類似定位但是卻運行完整Linux環境的低價中檔筆記本呢？（請看“",-1)),l(o,{href:"http://www.techrepublic.com/article/is-the-cloudbook-the-future-of-linux/"},{default:n(()=>[...t[0]||(t[0]=[e("Cloudbook是Linux的未來嗎？",-1)])]),_:1}),t[2]||(t[2]=e("”）其中的關鍵是這種設備要低成本並且符合普通消費者的要求。不要站在遊戲玩家/開發者的角度去思考了，記住普通消費者真正的需求 - 一個網頁瀏覽器，不會有更多了。這是Chromebook為什麼可以這麼輕鬆地成功。Google精確地知道消費者想要什麼，然後推出相應的產品。而面對Linux，一些公司仍然認為他們吸引買家的唯一途徑是高端昂貴的硬件。而有一點諷刺的是，口水戰中最經常聽到的卻是Linux只能在更慢更舊的硬件上運行。",-1))])]),t[19]||(t[19]=u("<p>最後，Linux需要看一看喬布斯傳（Book Of Jobs），搞清楚如何説服消費者們他們真正要的就是Linux。在公司裏和在家裏 -- 每個人都可以享受到Linux帶來的好處。説真的，開源社區怎麼可能做不到這點呢？Linux本身就已經帶有很多漂亮的時髦術語標籤：穩定性、可靠性、安全性、雲、免費 -- 再加上Linux實際已經進入到絕大多數人手中了（只是他們自己還不清楚罷了）。現在是時候讓他們知道這一點了。如果你是用Android或者Chromebooks，那麼你就在用（某種形式上的）Linux。</p><p>搞清楚消費者需求一直以來都是Linux社區的絆腳石。而且我知道 -- 太多的Linux開發都基於某個開發者有個特殊的想法。這意味着這些開發都針對的“微型市場”。是時候了，無論如何，讓Linux開發社區能夠進行全球性思考了。“一般用户有什麼需求，我們怎麼滿足他們？”讓我提幾個最基本的點。</p><p>一般用户想要：</p><ul><li>低價</li><li>設備和服務能無縫銜接</li><li>直觀而現代的設計</li><li>百分百可靠的瀏覽器體驗</li></ul><p>把這四點放在心中，應該可以輕鬆地以Linux為基礎開發出用户實際需要的產品。Google做到了...當然Linux社區也可以參照Google的工作並開發出更好的產品。把這些應用到集成AD這件事上，能開發出Exchange/Outlook的替代或者基於雲的羣件工具，就會發生一件非常特殊的事 -- 人們會為它買單。</p><p>你覺得Linux社區能夠提供消費者想要的東西嗎？在下邊的討論區裏分享一下你的看法。</p><hr>",7)),i("p",null,[t[6]||(t[6]=e("via: ",-1)),l(o,{href:"http://www.techrepublic.com/article/will-linux-ever-be-able-to-give-consumers-what-they-want/"},{default:n(()=>[...t[5]||(t[5]=[e("http://www.techrepublic.com/article/will-linux-ever-be-able-to-give-consumers-what-they-want/",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("作者：",-1)),l(o,{href:"http://www.techrepublic.com/search/?a=jack+wallen"},{default:n(()=>[...t[7]||(t[7]=[e("Jack Wallen",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),l(o,{href:"https://github.com/zpl1025"},{default:n(()=>[...t[8]||(t[8]=[e("zpl1025",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),l(o,{href:"http://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const k=r(x,[["render",b]]);export{h as __pageData,k as default};
